<template>
  <section class="lyrics-manager">
    <header class="manager-header">
      <div><p class="eyebrow"><span class="eyebrow-line"></span> Lyrics control room</p><h1 class="manager-title">Lời bài <span>hát.</span></h1><p class="manager-sub">Quản lý, chỉnh sửa và đồng bộ lời bài hát vào Supabase.</p></div>
      <button class="scan-btn" :class="{ scanning }" :disabled="scanning" @click="startScan"><span>{{ scanning ? '◌' : '⌁' }}</span>{{ scanning ? 'Đang kiểm tra...' : 'Kiểm tra lyrics' }}</button>
    </header>

    <div class="stats-grid"><div class="stat-chip"><span class="chip-icon plain">Aa</span><div><strong>{{ inventory.plain }}</strong><small>Có lời bài hát</small></div></div><div class="stat-chip"><span class="chip-icon manual">✎</span><div><strong>{{ inventory.manual }}</strong><small>Đã nhập thủ công</small></div></div><div class="stat-chip"><span class="chip-icon missing">?</span><div><strong>{{ inventory.missing }}</strong><small>Cần bổ sung</small></div></div></div>

    <div v-if="scanning || scanFinished" class="scan-panel"><div class="scan-panel-head"><div><p class="scan-label">LIBRARY SCAN</p><strong>{{ scanning ? `Đang kiểm tra ${scanIndex} / ${songs.length}` : scanCancelled ? `Đã dừng tại ${scanIndex} / ${songs.length}` : 'Đã hoàn tất lần quét' }}</strong></div><button v-if="scanning" class="cancel-btn" @click="cancelScan">Dừng quét</button><span v-else class="scan-done">✓ {{ scanCancelled ? 'STOPPED' : 'DONE' }}</span></div><div class="scan-progress"><span :style="{ width: `${scanProgress}%` }"></span></div><div class="scan-result-grid"><span><b>{{ scanSummary.already }}</b> đã có lyrics</span><span><b>{{ scanSummary.found }}</b> tìm thấy</span><span><b>{{ scanSummary.manual }}</b> cần sửa tay</span><span><b>{{ scanSummary.unavailable }}</b> chưa có nguồn</span></div></div>

    <div class="manager-toolbar"><label class="lyrics-search"><span>⌕</span><input v-model="searchQuery" placeholder="Tìm bài hát hoặc nghệ sĩ..." /></label><div class="filter-tabs"><button v-for="filter in filters" :key="filter.id" :class="{ active: activeFilter === filter.id }" @click="activeFilter = filter.id">{{ filter.label }} <small>{{ filter.count }}</small></button></div></div>

    <div class="lyrics-list" v-if="visibleSongs.length"><div class="lyrics-list-head"><span></span><span>BÀI HÁT</span><span>TRẠNG THÁI</span><span></span></div><article v-for="song in visibleSongs" :key="song.id" class="lyrics-row"><button class="row-art" @click="emit('play-song', song)"><img :src="song.cover || '/images/ChoCiu.jpg'" :alt="song.title" loading="lazy" /><span>▶</span></button><div class="row-copy"><strong>{{ song.title }}</strong><small>{{ song.artist }}</small></div><div class="row-status"><span class="status-pill" :class="songStatus(song)"><i></i>{{ statusLabel(songStatus(song)) }}</span><small v-if="songStatus(song) === 'plain'">Plain text</small><small v-else-if="songStatus(song) === 'manual'">Đã nhập</small><small v-else>Chưa có nội dung</small></div><button class="edit-btn" @click="openEditor(song)">{{ songStatus(song) === 'missing' ? 'Thêm lời' : 'Sửa' }} <span>→</span></button></article></div><div v-else class="empty-library"><div>⌕</div><strong>Không có bài hát phù hợp</strong><p>Thử đổi bộ lọc hoặc từ khóa tìm kiếm.</p></div>

    <div v-if="editorSong" class="editor-backdrop" @click.self="closeEditor"><section class="lyrics-editor"><div class="editor-top"><div><p class="scan-label">LYRICS EDITOR</p><h2>{{ editorSong.title }}</h2><span>{{ editorSong.artist }}</span></div><button class="close-editor" @click="closeEditor">×</button></div><div class="editor-hint"><span>Aa</span> Dán lời bài hát dạng văn bản thường. Khi bấm lưu, nội dung sẽ được đồng bộ trực tiếp vào Supabase.</div><textarea v-model="editorText" placeholder="Dán lời bài hát vào đây..."></textarea><p v-if="saveError" class="editor-error">{{ saveError }}</p><div class="editor-actions"><button class="cancel-editor" @click="closeEditor">Hủy</button><button class="save-editor" :disabled="!editorText.trim() || saving" @click="saveEditor">{{ saving ? 'Đang lưu...' : 'Lưu lyrics' }} <span>→</span></button></div></section></div>
  </section>
</template>

<script setup>
import { computed, ref } from 'vue';
import { getStoredLyrics, getLyricsInventory, hasLyrics, isTimedLyrics, lookupLyrics, saveLyrics } from '../services/lyricsService.js';
import { updateSong } from '../services/api.js';

const props = defineProps({ songs: { type: Array, default: () => [] } });
const emit = defineEmits(['play-song']);
const searchQuery = ref('');
const activeFilter = ref('all');
const refreshToken = ref(0);
const scanning = ref(false); const scanFinished = ref(false); const scanIndex = ref(0); const scanTotal = ref(0); const scanCancelRequested = ref(false); const scanCancelled = ref(false); const saving = ref(false);
const editorSong = ref(null); const editorText = ref(''); const editorOffset = ref(0); const saveError = ref('');
const scanSummary = ref({ already: 0, found: 0, manual: 0, unavailable: 0 });
const inventory = computed(() => { refreshToken.value; return getLyricsInventory(props.songs); });
const songStatus = (song) => { refreshToken.value; const stored = getStoredLyrics(song.id); const value = stored?.content || song.lyrics || song.metadata?.lyrics || ''; if (stored?.content) return stored.source === 'manual' ? 'manual' : 'plain'; return hasLyrics(value) ? 'plain' : 'missing'; };
const statusLabel = (status) => ({ synced: 'Có lời', plain: 'Có lời', manual: 'Đã nhập', missing: 'Chưa có' }[status]);
const filters = computed(() => [{ id: 'all', label: 'Tất cả', count: props.songs.length }, { id: 'plain', label: 'Có lời', count: inventory.value.plain }, { id: 'manual', label: 'Đã nhập', count: inventory.value.manual }, { id: 'missing', label: 'Cần bổ sung', count: inventory.value.missing }]);
const visibleSongs = computed(() => { const q = searchQuery.value.trim().toLowerCase(); return props.songs.filter((song) => { const matchesFilter = activeFilter.value === 'all' || songStatus(song) === activeFilter.value; const matchesQuery = !q || `${song.title} ${song.artist}`.toLowerCase().includes(q); return matchesFilter && matchesQuery; }); });
const scanProgress = computed(() => scanTotal.value ? Math.round((scanIndex.value / scanTotal.value) * 100) : 0);
const wait = (ms) => new Promise((resolve) => window.setTimeout(resolve, ms));
const openEditor = (song) => { const stored = getStoredLyrics(song.id); editorSong.value = song; editorText.value = stored?.content || song.lyrics || ''; editorOffset.value = Number(stored?.offsetMs || 0); saveError.value = ''; };
const closeEditor = () => { editorSong.value = null; editorText.value = ''; editorOffset.value = 0; saveError.value = ''; };
const saveEditor = async () => { if (!editorSong.value || !editorText.value.trim()) return; saving.value = true; saveError.value = ''; try { await updateSong(editorSong.value.id, { title: editorSong.value.title || '', artist: editorSong.value.artist || 'Unknown artist', cover: editorSong.value.cover || '', lyrics: editorText.value }); saveLyrics(editorSong.value.id, { content: editorText.value, source: 'supabase', offsetMs: Math.max(-5000, Math.min(5000, editorOffset.value)) }); refreshToken.value += 1; closeEditor(); } catch (error) { saveError.value = error?.message || 'Không thể đồng bộ lyrics vào Supabase.'; } finally { saving.value = false; } };
const cancelScan = () => { scanCancelRequested.value = true; scanCancelled.value = true; };
const lookupWithRetry = async (song) => { let result = await lookupLyrics(song); if (result.status === 'error') { await wait(120); result = await lookupLyrics(song); } return result; };
const startScan = async () => { if (scanning.value) return; scanning.value = true; scanFinished.value = false; scanCancelRequested.value = false; scanCancelled.value = false; scanIndex.value = 0; scanTotal.value = props.songs.length; scanSummary.value = { already: 0, found: 0, manual: 0, unavailable: 0 }; for (const song of props.songs) { if (scanCancelRequested.value) break; const stored = getStoredLyrics(song.id); const existing = stored?.content || song.lyrics || song.metadata?.lyrics || ''; if (hasLyrics(existing)) { scanSummary.value.already += 1; } else { const result = await lookupWithRetry(song); if (result.content) { saveLyrics(song.id, result); scanSummary.value.found += 1; } else if (result.status === 'error') scanSummary.value.manual += 1; else scanSummary.value.unavailable += 1; } scanIndex.value += 1; if (scanIndex.value % 6 === 0) await wait(0); } refreshToken.value += 1; scanning.value = false; scanFinished.value = true; };
</script>

<style scoped>
.lyrics-manager { min-height: 100%; padding: 0 clamp(22px, 4vw, 62px) 70px; animation: fade-up .55s var(--ease-out); }.manager-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; padding-top: clamp(34px, 5vw, 64px); margin-bottom: 34px; }.manager-title { margin-top: 13px; color: var(--text-main); font: 600 clamp(42px, 5.1vw, 69px)/.98 var(--font-display); letter-spacing: -3px; }.manager-title span { color: var(--gold-bright); }.manager-sub { max-width: 420px; margin-top: 15px; color: var(--text-sub); font-size: 13px; line-height: 1.5; }.scan-btn { display: inline-flex; align-items: center; gap: 10px; padding: 12px 15px; border: 1px solid rgba(245,185,122,.35); border-radius: 12px; background: rgba(245,185,122,.1); color: var(--gold-bright); font-size: 11px; font-weight: 700; cursor: pointer; white-space: nowrap; }.scan-btn:hover { border-color: var(--gold); background: rgba(245,185,122,.16); transform: translateY(-2px); }.scan-btn span { font-size: 17px; }.scan-btn.scanning span { animation: spin 1s linear infinite; }.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 25px; }.stat-chip { display: flex; align-items: center; gap: 10px; padding: 14px; border: 1px solid var(--hairline-soft); border-radius: 14px; background: var(--glass); }.chip-icon { display: flex; align-items: center; justify-content: center; width: 31px; height: 31px; border-radius: 10px; font: 600 12px var(--font-mono); }.chip-icon.synced { background: rgba(130,229,195,.11); color: var(--mint); }.chip-icon.plain { background: rgba(245,185,122,.11); color: var(--gold); }.chip-icon.manual { background: rgba(155,140,255,.13); color: var(--violet); }.chip-icon.missing { background: rgba(255,109,125,.11); color: var(--crimson); }.stat-chip strong { display: block; color: var(--text-main); font: 600 22px/1 var(--font-display); }.stat-chip small { display: block; margin-top: 3px; color: var(--text-faint); font-size: 9px; }.scan-panel { padding: 17px; margin-bottom: 24px; border: 1px solid rgba(245,185,122,.2); border-radius: 15px; background: linear-gradient(110deg, rgba(245,185,122,.1), rgba(155,140,255,.06)); }.scan-panel-head { display: flex; align-items: center; justify-content: space-between; }.scan-label { color: var(--gold); font: 9px var(--font-mono); letter-spacing: 1.7px; }.scan-panel-head strong { display: block; margin-top: 5px; color: var(--text-main); font: 600 15px var(--font-display); }.cancel-btn { border: 1px solid var(--hairline); border-radius: 8px; padding: 7px 9px; background: var(--glass); color: var(--text-sub); font-size: 10px; cursor: pointer; }.cancel-btn:hover { color: var(--crimson); }.scan-done { color: var(--mint); font: 9px var(--font-mono); letter-spacing: 1px; }.scan-progress { height: 5px; margin: 16px 0 13px; overflow: hidden; border-radius: 99px; background: rgba(255,255,255,.09); }.scan-progress span { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--gold), var(--coral)); box-shadow: 0 0 14px rgba(245,185,122,.45); transition: width .18s var(--ease-out); }.scan-result-grid { display: flex; flex-wrap: wrap; gap: 10px 18px; color: var(--text-sub); font-size: 9px; }.scan-result-grid b { color: var(--text-main); }.manager-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 18px; }.lyrics-search { display: flex; align-items: center; gap: 10px; width: min(320px, 100%); padding: 10px 12px; border: 1px solid var(--hairline-soft); border-radius: 11px; background: var(--glass); }.lyrics-search:focus-within { border-color: rgba(245,185,122,.55); }.lyrics-search span { color: var(--gold); font-size: 18px; }.lyrics-search input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--text-main); font-size: 11px; }.filter-tabs { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; }.filter-tabs button { border: 1px solid transparent; border-radius: 8px; padding: 8px 9px; background: transparent; color: var(--text-faint); cursor: pointer; font-size: 10px; }.filter-tabs button:hover, .filter-tabs button.active { border-color: var(--hairline); background: var(--glass); color: var(--text-main); }.filter-tabs button.active { color: var(--gold-bright); }.filter-tabs small { margin-left: 3px; color: var(--text-faint); font: 9px var(--font-mono); }.lyrics-list { border-top: 1px solid var(--hairline-soft); }.lyrics-list-head, .lyrics-row { display: grid; grid-template-columns: 53px minmax(240px, 1.5fr) minmax(150px, .8fr) 75px; align-items: center; gap: 16px; }.lyrics-list-head { grid-template-columns: 53px minmax(240px, 1.5fr) minmax(150px, .8fr) 75px; padding: 11px 14px; color: var(--text-faint); font: 9px var(--font-mono); letter-spacing: 1.2px; }.lyrics-list-head span:nth-child(2) { grid-column: 2; }.lyrics-row { position: relative; min-height: 67px; padding: 7px 14px; border-top: 1px solid var(--hairline-soft); border-radius: 10px; }.lyrics-row:hover { background: var(--glass); }.row-art { position: relative; width: 44px; height: 44px; margin-right: 9px; border: 0; border-radius: 9px; overflow: hidden; background: transparent; cursor: pointer; }.row-art img { width: 100%; height: 100%; object-fit: cover; }.row-art span { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(5,7,12,.52); color: var(--gold); opacity: 0; }.row-art:hover span { opacity: 1; }.row-copy { display: flex; flex-direction: column; min-width: 0; margin-left: -7px; }.row-copy strong { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }.row-copy small { margin-top: 5px; overflow: hidden; color: var(--text-sub); text-overflow: ellipsis; white-space: nowrap; font-size: 10px; }.row-status { grid-column: 3; display: flex; flex-direction: column; align-items: flex-start; gap: 5px; }.status-pill { display: inline-flex; align-items: center; gap: 6px; color: var(--text-sub); font-size: 10px; }.status-pill i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; box-shadow: 0 0 8px currentColor; }.status-pill.synced { color: var(--mint); }.status-pill.plain { color: var(--gold); }.status-pill.manual { color: var(--violet); }.status-pill.missing { color: var(--crimson); }.row-status small { color: var(--text-faint); font-size: 9px; }.edit-btn { justify-self: end; border: 1px solid var(--hairline-soft); border-radius: 8px; padding: 7px 8px; background: transparent; color: var(--text-sub); cursor: pointer; font-size: 10px; }.edit-btn:hover { border-color: rgba(245,185,122,.4); color: var(--gold); }.edit-btn span { margin-left: 4px; color: var(--gold); }.empty-library { padding: 65px 20px; text-align: center; }.empty-library > div { color: var(--gold); font-size: 25px; }.empty-library strong { display: block; margin-top: 12px; color: var(--text-main); font: 600 17px var(--font-display); }.empty-library p { margin-top: 7px; color: var(--text-sub); font-size: 11px; }.editor-backdrop { position: fixed; inset: 0; z-index: 340; display: flex; align-items: center; justify-content: center; padding: 20px; background: rgba(3,5,9,.73); backdrop-filter: blur(8px); }.lyrics-editor { width: min(620px, 100%); padding: 23px; border: 1px solid var(--hairline); border-radius: 18px; background: #141823; box-shadow: 0 25px 90px rgba(0,0,0,.45); }.editor-top { display: flex; justify-content: space-between; gap: 15px; }.editor-top h2 { margin-top: 7px; overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font: 600 21px var(--font-display); }.editor-top span { display: block; margin-top: 5px; color: var(--text-sub); font-size: 11px; }.close-editor { width: 31px; height: 31px; border: 1px solid var(--hairline); border-radius: 9px; background: var(--glass); color: var(--text-main); cursor: pointer; font-size: 20px; }.editor-hint { display: flex; gap: 8px; margin: 20px 0 11px; color: var(--text-sub); font-size: 10px; line-height: 1.4; }.editor-hint span { color: var(--gold); font-size: 17px; }.lyrics-editor textarea { display: block; width: 100%; min-height: 230px; resize: vertical; padding: 13px; border: 1px solid var(--hairline-soft); border-radius: 11px; outline: 0; background: rgba(3,5,9,.38); color: var(--text-main); font: 12px/1.65 var(--font-body); }.lyrics-editor textarea:focus { border-color: rgba(245,185,122,.55); }.timing-row { display: flex; align-items: center; gap: 15px; padding: 17px 0; }.timing-row label { color: var(--text-main); font-size: 11px; font-weight: 700; }.timing-row p { margin-top: 4px; color: var(--text-faint); font-size: 9px; }.offset-control { display: flex; align-items: center; gap: 8px; margin-left: auto; }.offset-control button { width: 27px; height: 27px; border: 1px solid var(--hairline); border-radius: 7px; background: var(--glass); color: var(--gold); cursor: pointer; }.offset-control output { width: 67px; color: var(--text-main); text-align: center; font: 10px var(--font-mono); }.reset-offset { border: 0; background: transparent; color: var(--text-faint); cursor: pointer; font-size: 9px; }.reset-offset:hover { color: var(--gold); }.editor-actions { display: flex; justify-content: flex-end; gap: 9px; padding-top: 15px; border-top: 1px solid var(--hairline-soft); }.cancel-editor, .save-editor { border-radius: 9px; padding: 10px 13px; cursor: pointer; font-size: 11px; }.cancel-editor { border: 1px solid var(--hairline); background: transparent; color: var(--text-sub); }.save-editor { border: 0; background: linear-gradient(130deg, var(--gold-bright), var(--gold)); color: #171019; font-weight: 800; }.save-editor span { margin-left: 8px; font-size: 16px; }
@media (max-width: 800px) { .stats-grid { grid-template-columns: repeat(2, 1fr); }.manager-header { align-items: flex-start; flex-direction: column; }.manager-toolbar { align-items: stretch; flex-direction: column; }.lyrics-search { width: 100%; }.filter-tabs { justify-content: flex-start; }.lyrics-list-head { display: none; }.lyrics-row { grid-template-columns: 53px minmax(0, 1fr) 65px; gap: 9px; padding: 7px 8px; }.row-status { grid-column: 3; }.row-status small { display: none; }.edit-btn { grid-column: 2 / 4; justify-self: end; margin-top: -25px; }.row-copy { grid-column: 2; }.row-art { grid-column: 1; grid-row: 1; } }
@media (max-width: 520px) { .lyrics-manager { padding: 0 16px 92px; }.manager-header { padding-top: 31px; }.manager-title { font-size: 42px; }.stats-grid { gap: 8px; }.stat-chip { padding: 11px; }.stat-chip strong { font-size: 19px; }.scan-result-grid { display: grid; grid-template-columns: 1fr 1fr; }.timing-row { align-items: flex-start; flex-wrap: wrap; }.offset-control { margin-left: 0; }.reset-offset { margin-left: auto; }.lyrics-editor { padding: 18px; }.lyrics-editor textarea { min-height: 190px; } }
</style>
